 84 |       createOperatorSubscriber(
 85 |         subscriber,
 86 |         (value) => {
 87 |           // Value from our source. Add it to all pending buffers.
 88 |           for (const buffer of buffers) {
 89 |             buffer.push(value);
 90 |           }
 91 |         },
 92 |         () => {
 93 |           // Source complete. Emit all pending buffers.
 94 |           while (buffers.length > 0) {
 95 |             subscriber.next(buffers.shift()!);
 96 |           }
 97 |           subscriber.complete();
 98 |         }
 99 |       )
100 |     );
101 |   });
