127 |           // twice. Subscription unsubscribe is idempotent.
128 |           if (teardown.closed || teardown._hasParent(this)) {
129 |             return;
130 |           }
131 |           teardown._addParent(this);
132 |         }
133 |         (this._finalizers = this._finalizers ?? []).push(teardown);
134 |       }
135 |     }
136 |   }
137 | 
138 |   /**
139 |    * Checks to see if a this subscription already has a particular parent.
140 |    * This will signal that this subscription has already been added to the parent in question.
141 |    * @param parent the parent to check for
142 |    */
143 |   private _hasParent(parent: Subscription) {
144 |     const { _parentage } = this;
145 |     return _parentage === parent || (Array.isArray(_parentage) && _parentage.includes(parent));
146 |   }
147 | 
148 |   /**
149 |    * Adds a parent to this subscription so it can be removed from the parent if it
150 |    * unsubscribes on it's own.
151 |    *
152 |    * NOTE: THIS ASSUMES THAT {@link _hasParent} HAS ALREADY BEEN CHECKED.
153 |    * @param parent The parent subscription to add
154 |    */
155 |   private _addParent(parent: Subscription) {
156 |     const { _parentage } = this;
157 |     this._parentage = Array.isArray(_parentage) ? (_parentage.push(parent), _parentage) : _parentage ? [_parentage, parent] : parent;
158 |   }
159 | 
160 |   /**
161 |    * Called on a child when it is removed via {@link #remove}.
162 |    * @param parent The parent to remove
163 |    */
164 |   private _removeParent(parent: Subscription) {
165 |     const { _parentage } = this;
166 |     if (_parentage === parent) {
167 |       this._parentage = null;
168 |     } else if (Array.isArray(_parentage)) {
169 |       arrRemove(_parentage, parent);
