182 |    *
183 |    * All finalizer instances are removed to free up memory upon unsubscription.
184 |    *
185 |    * @param teardown The finalizer to remove from this subscription
186 |    */
187 |   remove(teardown: Exclude<TeardownLogic, void>): void {
188 |     const { _finalizers } = this;
189 |     _finalizers && arrRemove(_finalizers, teardown);
190 | 
191 |     if (teardown instanceof Subscription) {
192 |       teardown._removeParent(this);
193 |     }
194 |   }
195 | }
