 24 |   /** @deprecated Internal implementation detail, do not use directly. Will be made internal in v8. */
 25 |   isStopped = false;
 26 |   /** @deprecated Internal implementation detail, do not use directly. Will be made internal in v8. */
 27 |   hasError = false;
 28 |   /** @deprecated Internal implementation detail, do not use directly. Will be made internal in v8. */
