    while (true) {
      const result = await reader.read();
      if (result.done) {
        done = true;
        return;
      }
      yield result.value!;
    }
  } finally {
    if (!done && reader.cancel) {
      try {
        await reader.cancel();
      } finally {
        reader.releaseLock();
      }
    } else {
      reader.releaseLock();
    }
  }
}

